using Godot;
using System;
public partial class ValueCurveOperations:RefCounted
{
    private static Curve? Current(Control owner)=>owner.Get("curve").As<Curve>();
    public Curve preset(string name)
    {
        var result=new Curve();int segments=name=="Exponential"?4:name=="Sine"?2:name=="Step"?16:1;for(int i=0;i<=segments;i++){double x=(double)i/segments,y=x,slope=1;switch(name){case "Quadratic":y=x*x;slope=2*x;break;case "Exponential":y=(Math.Pow(2,8*x)-1)/255;slope=8*Math.Log(2)*Math.Pow(2,8*x)/255;break;case "Ease out":y=1-Math.Pow(1-x,3);slope=3*Math.Pow(1-x,2);break;case "Smoothstep":y=x*x*(3-2*x);slope=6*x*(1-x);break;case "Sine":y=(1-Math.Cos(Math.PI*x))/2;slope=Math.PI*Math.Sin(Math.PI*x)/2;break;case "Step":y=i==segments?1:0;break;}result.AddPoint(new Vector2((float)x,(float)y),name=="Step"?0:(float)slope,name=="Step"?0:(float)slope,name=="Step"?Curve.TangentMode.Linear:Curve.TangentMode.Free,name=="Step"?Curve.TangentMode.Linear:Curve.TangentMode.Free);}return result;
    }
    public Curve for_key(Resource key){var curve=key.Get("value_curve").As<Curve>();if(curve!=null)return (Curve)curve.Duplicate();var result=preset("Linear");if(key.Get("interpolation").AsInt32()==1){result.ClearPoints();for(int i=0;i<17;i++){float x=i/16f;result.AddPoint(new Vector2(x,Mathf.Ease(x,key.Get("attenuation").AsSingle())),0,0,Curve.TangentMode.Linear,Curve.TangentMode.Linear);}}return result;}
    public double template_value(string name,double adjustment,double x)=>name switch{"Ease"=>adjustment>=0?1-Math.Pow(1-x,1+adjustment):Math.Pow(x,1-adjustment),"Smoothstep"=>x+(x*x*(3-2*x)-x)*Math.Clamp(adjustment,0,1),"Sin wave"=>x+.25*(Math.Sin(Math.Tau*adjustment*x)-x*Math.Sin(Math.Tau*adjustment)),"Step"=>Math.Floor(x*Math.Max(1,Mathf.Round((float)adjustment)))/Math.Max(1,Mathf.Round((float)adjustment)),_=>x};
    public Curve template(string name,double adjustment)
    {
        if(name=="Linear")return preset("Linear");var result=new Curve();if(name=="Step"){int steps=Math.Clamp(Mathf.RoundToInt((float)adjustment),1,64);result.AddPoint(Vector2.Zero,0,0,Curve.TangentMode.Linear,Curve.TangentMode.Linear);for(int i=1;i<=steps;i++){float x=(float)i/steps;result.AddPoint(new Vector2(x-.00001f,(float)(i-1)/steps),0,0,Curve.TangentMode.Linear,Curve.TangentMode.Linear);result.AddPoint(new Vector2(x,(float)i/steps),0,0,Curve.TangentMode.Linear,Curve.TangentMode.Linear);}}else{int samples=name=="Sin wave"?Math.Max(8,(int)(Math.Abs(adjustment)*8)):name=="Smoothstep"?1:8;for(int i=0;i<=samples;i++){double x=(double)i/samples,lo=Math.Max(0,x-.0001),hi=Math.Min(1,x+.0001),slope=(template_value(name,adjustment,hi)-template_value(name,adjustment,lo))/(hi-lo);result.AddPoint(new Vector2((float)x,(float)template_value(name,adjustment,x)),(float)slope,(float)slope,Curve.TangentMode.Free,Curve.TangentMode.Free);}}return result;
    }
    public Rect2 graph_rect(Control owner){float margin=owner.Get("editable").AsBool()?12:4;return new Rect2(new Vector2(margin,margin),(owner.Size-new Vector2(margin*2,margin*2)).Max(Vector2.One));}
    public Vector2 graph_point(Control owner,Vector2 point){var rect=graph_rect(owner);return rect.Position+new Vector2(point.X*rect.Size.X,(1-point.Y)*rect.Size.Y);}
    public Vector2 normalized(Control owner,Vector2 position){var rect=graph_rect(owner);return new Vector2(Math.Clamp((position.X-rect.Position.X)/rect.Size.X,.001f,.999f),Math.Clamp(1-(position.Y-rect.Position.Y)/rect.Size.Y,0,1));}
    public Vector2 tangent_position(Control owner,int index,int side){var curve=Current(owner)!;var origin=graph_point(owner,curve.GetPointPosition(index));float slope=side<0?curve.GetPointLeftTangent(index):curve.GetPointRightTangent(index);var mode=side<0?curve.GetPointLeftMode(index):curve.GetPointRightMode(index);if(mode==Curve.TangentMode.Linear&&index+side>=0&&index+side<curve.PointCount){var difference=curve.GetPointPosition(index+side)-curve.GetPointPosition(index);slope=Math.Abs(difference.X)>.000001?difference.Y/difference.X:0;}var rect=graph_rect(owner);var direction=new Vector2(rect.Size.X,-slope*rect.Size.Y).Normalized()*side;return origin+direction*48;}
    public void reset_tangents(Control owner){var curve=Current(owner);if(curve==null||curve.PointCount==0)return;cancel_edit(owner);curve=Current(owner)!;int index=Math.Clamp(owner.Get("selected_point").AsInt32(),0,curve.PointCount-1);owner.Set("selected_point",index);owner.EmitSignal("edit_started");curve.SetPointLeftMode(index,Curve.TangentMode.Linear);curve.SetPointRightMode(index,Curve.TangentMode.Linear);owner.Set("stepped",false);owner.EmitSignal("preview_changed",curve);owner.EmitSignal("edit_committed");owner.QueueRedraw();}
    public void cancel_edit(Control owner){if(owner.Get("_drag_point").AsInt32()<0)return;owner.Set("_drag_point",-1);owner.Set("_drag_handle",0);owner.Set("curve",owner.Get("_before"));owner.EmitSignal("edit_cancelled");owner.QueueRedraw();}
    public StyleBoxFlat style(){var result=new StyleBoxFlat{BgColor=new Color("14251f"),BorderColor=new Color("3c7667")};result.SetBorderWidthAll(1);result.SetCornerRadiusAll(5);return result;}
    public void draw(Control owner)
    {
        using var background=style();owner.DrawStyleBox(background,new Rect2(Vector2.Zero,owner.Size));bool editable=owner.Get("editable").AsBool();if(editable)for(int i=0;i<5;i++){float fraction=i/4f;owner.DrawLine(graph_point(owner,new Vector2(fraction,0)),graph_point(owner,new Vector2(fraction,1)),new Color(1,1,1,.08f));owner.DrawLine(graph_point(owner,new Vector2(0,fraction)),graph_point(owner,new Vector2(1,fraction)),new Color(1,1,1,.08f));}var curve=Current(owner);bool stepped=owner.Get("stepped").AsBool();var points=new Vector2[81];for(int i=0;i<81;i++){float x=i/80f,y=stepped?(x<1?0:1):curve?.Sample(x)??x;points[i]=graph_point(owner,new Vector2(x,y));}owner.DrawPolyline(points,new Color("8ae4cb"),2,true);if(!editable||curve==null||curve.PointCount==0)return;int selected=Math.Clamp(owner.Get("selected_point").AsInt32(),0,curve.PointCount-1);owner.Set("selected_point",selected);foreach(int side in new[]{-1,1}){if(selected+side<0||selected+side>=curve.PointCount)continue;var handle=tangent_position(owner,selected,side);owner.DrawLine(graph_point(owner,curve.GetPointPosition(selected)),handle,new Color("dfb677"),1,true);owner.DrawRect(new Rect2(handle-new Vector2(4,4),new Vector2(8,8)),new Color("ffce80"));}for(int i=0;i<curve.PointCount;i++)owner.DrawCircle(graph_point(owner,curve.GetPointPosition(i)),4,new Color(i==selected?"ffce80":"d5f8ed"));
    }
}
